$Politics_12_01 = '12.1 Informes de Negocios, Listas e Información Propietaria';
$Politics_12_01_text = 'Al aceptar el Acuerdo, los IBOs y los Clientes reconocen que los informes de negocios, la identidad y la información de contacto de los Clientes, IBOs y posibles Clientes o IBOs (incluida la disponible en chats grupales), información sobre la genealogía de EVO Global o de un IBO, y cualquier otra información financiera, técnica o de otro tipo que no sea de conocimiento general y/o sea de naturaleza sensible y que sea circulada por EVO Global o pertenezca al negocio de EVO Global, ya sea escrita o de otra forma, ya sea que esa información sea recibida directamente de EVO Global o de otros IBOs, son información confidencial y propietaria y secretos comerciales que pertenecen a Evo Movement International S.A. de C.V.';

    //-------------------------//

$Politics_12_02 = '12.2 Obligación de Confidencialidad';
$Politics_12_02_text = 'Los IBOs no deben usar la Información Confidencial y Secretos Comerciales de Evo Movement International S.A. de C.V. para ningún propósito que no sea promover el negocio de EVO Global de un IBO. Un IBO nunca puede divulgar la Información Confidencial y Secretos Comerciales no públicos de Evo Movement International S.A. de C.V. a nadie fuera de EVO Global sin el consentimiento escrito de la dirección de EVO Global.';

    //-------------------------//

$Politics_12_03 = '12.3 Incumplimiento y Remedios';
$Politics_12_03_text = 'Los IBOs reconocen que la Información Confidencial y Secretos Comerciales no públicos de EVO Global son de tal carácter que los hace únicos, y que la divulgación o uso de los mismos en violación del §12.1 et seq. resultará en daño inmediato e irreparable a EVO Global y a los negocios de EVO Global de los IBOs. Además de recuperar cualquier daño, EVO Global y sus IBOs tendrán derecho a un alivio injuntivo acelerado contra cualquier IBO que viole esta disposición en cualquier acción para hacer cumplir sus derechos bajo esta sección. EVO Global puede buscar dicho alivio injuntivo de forma acelerada bajo las leyes internacionales y mexicanas aplicables. La parte prevaleciente tendrá derecho a una adjudicación de honorarios de abogados, costos judiciales y gastos.';

    //-------------------------//

$Politics_12_04 = '12.4 Devolución de Materiales';
$Politics_12_04_text = 'Un IBO debe devolver inmediatamente a EVO Global el original y todas las copias de toda la Información Confidencial y Secretos Comerciales de EVO Global en posesión de dicha persona al (1) terminar este Acuerdo, o (2) demanda de EVO Global.';

